import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as r,j as i,G as t,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse(`{"title":"Epstein Files Transparency Act","description":"","frontmatter":{"legisId":"2025-11-19-epstein-files-transparency-act","title":"Epstein Files Transparency Act","displayTitle":"Epstein Files Transparency Act","lawNumber":"119-38","billNumber":"H.R. 4405","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ38.xml","publishDate":"2025-11-19T00:00:00-05:00","industries":["law-enforcement","government-operations"],"agencies":["Department of Justice","Federal Bureau of Investigation","United States Attorneys' Offices"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Epstein Files Transparency Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-11-19-epstein-files-transparency-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Epstein Files Transparency Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-11-19-epstein-files-transparency-act\\",\\"datePublished\\":\\"2025-11-19T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-11-19-epstein-files-transparency-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-11-19-epstein-files-transparency-act.md","filePath":"congress-bills/2025-11-19-epstein-files-transparency-act.md","lastUpdated":1788887623000}`),c={name:"congress-bills/2025-11-19-epstein-files-transparency-act.md"},g=Object.assign(c,{setup(d){return(p,e)=>(r(),n("div",null,[e[0]||(e[0]=i("h1",{id:"epstein-files-transparency-act",tabindex:"-1"},[l("Epstein Files Transparency Act "),i("a",{class:"header-anchor",href:"#epstein-files-transparency-act","aria-label":'Permalink to "Epstein Files Transparency Act"'},"​")],-1)),t(a),t(s,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Wednesday, November 19, 2025. Public Law 119-38, H.R. 4405.</p><p><strong>Headline:</strong> The law requires the Justice Department to publish searchable, downloadable Epstein-related records within 30 days.</p><p><strong>Why it matters:</strong> The measure compels broad public disclosure while preserving narrow protections for victims, active cases, graphic material, and national security information.</p><p><strong>What the law does:</strong></p><ul><li>Releases unclassified records about Jeffrey Epstein, Ghislaine Maxwell, related people and entities, investigations, travel, agreements, detention, death, and possible evidence concealment or destruction.</li><li>Bars withholding, delays, or redactions based only on embarrassment, reputational harm, or political sensitivity.</li><li>Allows limited withholding for victim privacy, child sexual abuse material, active federal cases, images of death or injury, and properly classified information.</li><li>Requires public explanations for every redaction, efforts to declassify covered information, and unclassified summaries of information that remains classified.</li><li>Requires a report to the House and Senate Judiciary Committees within 15 days after release detailing disclosures, withheld records, redactions, and named government officials or politically exposed persons.</li></ul><p><strong>Who it affects:</strong></p><ul><li>The Department of Justice, Federal Bureau of Investigation, and United States Attorneys’ Offices.</li><li>Epstein victims, people and entities named in the records, and officials overseeing congressional review.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Provides online access to searchable and downloadable government records about Epstein and related investigations.</li><li>Protects victims’ identifying information and other narrowly restricted material from public release.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="epstein-files-transparency-act-1" tabindex="-1">Epstein Files Transparency Act <a class="header-anchor" href="#epstein-files-transparency-act-1" aria-label="Permalink to &quot;Epstein Files Transparency Act&quot;">​</a></h3><p>The law requires the Attorney General to publish, within 30 days, searchable and downloadable copies of all unclassified Justice Department records related to Jeffrey Epstein, his associates, activities, detention, and death. It allows limited redactions or withholding for victim privacy, child sexual abuse material, active cases, graphic images, and properly classified national security information, while requiring public explanations and a follow-up report to Congress.</p><p><strong>Key takeaways:</strong></p><ul><li>The required release covers records held by the Justice Department, FBI, and U.S. Attorneys’ Offices concerning Epstein, Ghislaine Maxwell, related people and entities, travel, agreements, investigations, internal decisions, possible destruction or concealment of evidence, detention, and death.</li><li>Records may not be withheld, delayed, or redacted merely to avoid embarrassment, reputational harm, or political sensitivity.</li><li>Permitted withholding must be limited to protected portions involving victim privacy, child sexual abuse material, active federal cases, images of death or injury, or properly classified national security information.</li><li>The Attorney General must publicly justify every redaction, seek to declassify covered information as much as possible, and provide unclassified summaries when information must remain classified.</li><li>Within 15 days after completing the release, the Attorney General must report to the House and Senate Judiciary Committees on released and withheld records, redactions, and government officials or politically exposed persons named in the released materials.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ38.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ38.xml</a></p>',15))]))}});export{h as __pageData,g as default};
